//! Signal-token administration's HTTP surface (mint, list, revoke): each
//! handler names the caller as an operator and calls its action
//! (`crate::actions::settings`), where every rule lives. Kind-specific
//! signal enumeration and firing routes live in `signal.rs` and are
//! general-purpose.
//!
//! Token model (show-once): the value (`wft-` + six words, see
//! `weft_core::signal_token`) is generated by the dispatcher (or the broker, for an
//! instance token a program mints, through the same
//! `weft_access_store::instance_tokens::mint`), returned EXACTLY ONCE in
//! the mint response, and stored only as a sha256 hash plus a display
//! recognizer. Listing returns metadata only; no endpoint can re-reveal a
//! token. Revocation addresses the token's id, never its value.
//!
//! An external consumer (a client that listens for + answers a project's
//! waiting nodes) hits:
//!   - `POST /signal-tokens` (mint), `GET /signal-tokens` (list),
//!     `DELETE /signal-tokens/{id}` (revoke): tenant-authenticated admin.
//!   - `GET /signal-token/signals`, `DELETE /signal-token/signals`,
//!     `GET /signal-token/health`, and the node displays under
//!     `/signal-token/displays` (`api/display.rs`): the token itself
//!     authenticates, via `Authorization: Bearer wft-...` (never in the
//!     URL, where proxies and access logs would capture it).
//!   - `POST /signal/{token}` (fire), `DELETE /signal/{token}` (cancel):
//!     per-SIGNAL fire tokens, a separate credential whose whole job is to
//!     be a paste-able URL.
//! No kind-specific endpoints in the dispatcher.

use axum::{extract::{Path, State}, http::StatusCode, Json};

use crate::actions::{settings, Actor, Refused};
use crate::authenticator::CallerTenant;
use crate::state::DispatcherState;
use weft_core::signal_token::{MintTokenRequest, MintedToken, TokenSummary};

pub async fn mint_token(
    State(state): State<DispatcherState>,
    caller: CallerTenant,
    Json(body): Json<MintTokenRequest>,
) -> Result<Json<MintedToken>, Refused> {
    Ok(Json(settings::signal_token_mint(&state, &Actor::operator(caller.0), body).await?))
}

pub async fn list_tokens(State(state): State<DispatcherState>, caller: CallerTenant) -> Result<Json<Vec<TokenSummary>>, Refused> {
    Ok(Json(settings::signal_tokens_list(&state, &Actor::operator(caller.0)).await?))
}

/// DELETE /signal-tokens/{id}. A token that is not there (revoked
/// already, or gone with its project) answers 404 with the
/// `x-weft-not-found: token` marker, so a client cleaning up after
/// itself reads it as done rather than as a failure.
pub async fn revoke_token(
    State(state): State<DispatcherState>,
    caller: CallerTenant,
    Path(id): Path<uuid::Uuid>,
) -> Result<axum::response::Response, Refused> {
    use axum::response::IntoResponse;
    if settings::signal_token_revoke(&state, &Actor::operator(caller.0), id).await? {
        Ok(StatusCode::NO_CONTENT.into_response())
    } else {
        Ok((StatusCode::NOT_FOUND, [("x-weft-not-found", "token")], format!("no token with id {id}")).into_response())
    }
}
